/* Klingon Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Kahless": "Kahless the Unforgettable, founder of the Klingon Empire; the most revered Klingon name.", "Worf": "Worf, son of Mogh, the most famous Klingon of Starfleet.", "Martok": "Martok, the great Klingon general and chancellor.", "Gowron": "Gowron, chancellor of the High Council.", "Kurn": "Kurn, Worf's younger brother.", "Lursa": "Lursa of the House of Duras, with her sister B'Etor.", "Son of Mogh": "Worf's lineage name: Worf, son of Mogh.", "House of Duras": "The great treacherous house of Duras, Lursa and B'Etor.", "House of Martok": "The house of the common-born chancellor Martok.", "House of Kor": "The house of Dahar Master Kor."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Kahless';
console.log(lookup(q));

